INSERT INTO public.look_inspirations (look_id, slug, title, description, styling_tip, category, sort_order) VALUES
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'living-room', 'Champagne Living Room', 'A calm ivory living room layered with champagne glass, brushed gold and soft candlelight.', 'Keep walls and upholstery ivory so the metallics read as jewellery rather than decoration.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'tree', 'Glass and Champagne Tree', 'A softly lit tree dressed in champagne glass, pearl and matt ivory baubles with wired ribbon.', 'Mix matt, glass and pearl finishes in the same tone so the tree glows instead of glittering.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'table', 'Champagne Dining Table', 'An ivory linen table with gold rimmed glassware, taper candles and eucalyptus.', 'Run a low line of greenery down the centre so guests can still see each other across the table.', 'table', 3),
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'mantel', 'Gilded Mantel', 'A restrained mantel with a champagne garland, ivory stockings and clustered candles.', 'Anchor the garland at both ends and let one side drape lower for an effortless asymmetry.', 'mantel', 4),
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'sideboard', 'Champagne Sideboard', 'A sideboard styled with glass bell jars, candles and a small lit tree.', 'Group objects in odd numbers and vary heights to keep the display looking curated.', 'shelf', 5),
((SELECT id FROM public.christmas_looks WHERE slug='elegant-gold-champagne'), 'details', 'Champagne Details', 'Close-up styling: ribbon, glass baubles and gilded place settings.', 'Repeat two metals at most — brushed gold and clear glass — for a cohesive finish.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'living-room', 'Frosted Living Room', 'A cool white room layered with silver, crystal and frosted branches.', 'Choose cool white lights rather than warm white to keep the icy effect convincing.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'tree', 'Crystal and Silver Tree', 'A flocked tree hung with crystal drops, snowflakes and mirrored baubles.', 'Hang the heaviest crystal drops on the outer branch tips so they catch the light and spin.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'window', 'Frosted Window Styling', 'Icicle lights, hanging snowflakes and frosted foliage at the window.', 'Hang snowflakes at staggered heights on clear thread so they appear to float.', 'window', 3),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'staircase', 'Icy Staircase Garland', 'A frosted garland threaded with lights, crystal drops and silver ribbon.', 'Wind the lights through the garland before adding decorations so the wire disappears.', 'staircase', 4),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'mantel', 'Snowy Mantel', 'A mantel of frosted greenery, silver stockings and glass hurricanes.', 'Add a few pinecones dusted white to break up the shine with texture.', 'mantel', 5),
((SELECT id FROM public.christmas_looks WHERE slug='winter-wonderland'), 'details', 'Crystal Details', 'Close-up crystal drops, glass snowflakes and frosted sprigs.', 'Mix clear glass with frosted matt finishes so the display has depth, not just glare.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'living-room', 'Scandi Living Room', 'Pale wood, warm white textiles and a simply dressed tree.', 'Leave empty space around each decoration — restraint is the whole look.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'tree', 'Simple Nordic Tree', 'A slim tree with wooden ornaments, straw stars and warm white lights.', 'Stick to three ornament types repeated around the tree for a calm, deliberate rhythm.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'shelf', 'Nordic Shelf Styling', 'Wooden candle holders, paper stars and a few red accents on open shelving.', 'Line up candles of different heights in a row for a simple, striking display.', 'shelf', 3),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'window', 'Paper Stars at the Window', 'Hanging paper stars and simple candle bridges in a bright window.', 'Hang stars at three different drops so the window has depth from the street.', 'window', 4),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'table', 'Nordic Table Setting', 'Natural linen, stoneware and spruce sprigs with simple candles.', 'Tie a spruce sprig to each napkin with twine — one detail is enough per setting.', 'table', 5),
((SELECT id FROM public.christmas_looks WHERE slug='nordic-christmas'), 'details', 'Nordic Details', 'Twine, spruce, wooden ornaments and a single red accent.', 'Use twine instead of ribbon — it keeps the natural, handmade feeling.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'living-room', 'Woodland Living Room', 'Deep greens, pine branches and natural textures around a warm fire.', 'Bring in three different types of foliage so the greenery looks foraged, not bought.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'tree', 'Foraged Woodland Tree', 'A real tree dressed with cones, dried orange slices and wooden ornaments.', 'Add dried citrus last so it sits on the outside of the branches and catches the light.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'front-door', 'Foraged Front Door Wreath', 'A generous wreath of pine, eucalyptus, cones and berries.', 'Build the wreath asymmetrically, weighting one side, so it looks gathered rather than manufactured.', 'door', 3),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'garland', 'Pine Garland', 'A thick pine garland with cones, berries and hidden warm lights.', 'Wire cones on in clusters of three rather than spacing them evenly.', 'garland', 4),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'mantel', 'Woodland Mantel', 'A log-store mantel of greenery, candles, cones and antler-style detail.', 'Let the greenery trail unevenly past the mantel edge for a natural finish.', 'mantel', 5),
((SELECT id FROM public.christmas_looks WHERE slug='natural-woodland'), 'details', 'Natural Details', 'Close-up cones, berries, dried citrus and twine-tied bundles.', 'Dry your own citrus slices low and slow — they last for several seasons.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'living-room', 'Tartan Country Living Room', 'Rich greens, tartan throws and heritage patterns around a real tree.', 'Repeat the tartan at least three times around the room so it reads as a scheme.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'tree', 'Tartan Ribbon Tree', 'A full green tree with tartan bows, red baubles and brass detail.', 'Cut tartan ribbon on the diagonal for tails that hang cleanly.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'staircase', 'Tartan Staircase', 'A green garland threaded with tartan ribbon down a timber banister.', 'Tie a bow at every third spindle so the rhythm feels regular from below.', 'staircase', 3),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'table', 'Tartan Christmas Table', 'A tartan runner, brass candlesticks and holly-trimmed place settings.', 'Keep crockery plain white so the tartan does the talking.', 'table', 4),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'mantel', 'Heritage Mantel', 'Green garland, tartan stockings and brass candlesticks over a fire.', 'Hang stockings in descending size order for a tidy, traditional line.', 'mantel', 5),
((SELECT id FROM public.christmas_looks WHERE slug='classic-green-tartan'), 'front-door', 'Tartan Door Wreath', 'A holly and ivy wreath finished with a generous tartan bow.', 'Make the bow oversized — on a front door it should be visible from the gate.', 'door', 6),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'tree', 'Candy Cane Tree', 'A red and white striped tree with candy canes, ribbon and peppermint baubles.', 'Alternate stripe direction on ribbon and baubles so the pattern stays lively.', 'tree', 1),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'table', 'Peppermint Table', 'A crisp white table with red striped napkins and candy cane place settings.', 'Tie a candy cane to each napkin — it doubles as a place marker.', 'table', 2),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'mantel', 'Candy Cane Mantel', 'White garland with red stripes, candy jars and striped stockings.', 'Fill clear jars with sweets — they add colour and cost very little.', 'mantel', 3),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'front-door', 'Striped Door Welcome', 'A red and white wreath with candy cane trim beside a striped lantern.', 'Wrap the ribbon in a spiral around the wreath to mimic a candy cane.', 'door', 4),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'living-room', 'Playful Family Living Room', 'A cheerful red and white room with striped cushions and sweet jars.', 'Keep the base of the room white so the red never tips into overwhelming.', 'room', 5),
((SELECT id FROM public.christmas_looks WHERE slug='candy-cane-christmas'), 'details', 'Peppermint Details', 'Close-up candy canes, striped ribbon and peppermint baubles.', 'Group sweets by shape rather than colour for a neater display.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'living-room', 'Nostalgic Living Room', 'Heirloom decorations, warm lamplight and well-loved furniture.', 'Display older ornaments at eye level where their patina can be seen.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'tree', 'Heirloom Glass Tree', 'Antique glass ornaments and vintage coloured bulbs on a full tree.', 'Hang the oldest ornaments deeper in the branches where they are protected.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'mantel', 'Vintage Mantel', 'Old cards strung on twine, brass candlesticks and hand-me-down stockings.', 'Peg vintage Christmas cards along twine for instant, free nostalgia.', 'mantel', 3),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'shelf', 'Curiosity Shelf', 'A dresser of glass ornaments, vintage tins and old ceramics.', 'Cluster ornaments in a glass bowl so a small collection looks abundant.', 'shelf', 4),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'table', 'Vintage Table', 'Mismatched china, lace linen and brass candlesticks.', 'Mismatched plates look intentional when the linens all match.', 'table', 5),
((SELECT id FROM public.christmas_looks WHERE slug='vintage-christmas'), 'details', 'Heirloom Details', 'Close-up mercury glass, velvet ribbon and old paper tags.', 'Swap modern gift tags for brown paper and string to match the scheme.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'living-room', 'Opulent Living Room', 'A statement tree, velvet seating and layered metallic decoration.', 'Layer three textures — velvet, glass and metal — in every part of the room.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'tree', 'Statement Luxury Tree', 'A tall, densely decorated tree with ribbon cascades and oversized baubles.', 'Work ribbon vertically from top to bottom in wide cascades for a designer finish.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'staircase', 'Grand Staircase', 'A lavish garland with oversized baubles winding a sweeping staircase.', 'Double up two garlands for the depth that makes a staircase look expensive.', 'staircase', 3),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'table', 'Luxury Dining Table', 'Charger plates, crystal, candelabra and an abundant centrepiece.', 'Raise the centrepiece on a candelabra so the table still feels generous underneath.', 'table', 4),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'mantel', 'Marble Mantel', 'A marble fireplace layered with foliage, metallics and velvet stockings.', 'Let the garland spill generously at both ends — sparse garlands look cheap.', 'mantel', 5),
((SELECT id FROM public.christmas_looks WHERE slug='luxury-christmas'), 'details', 'Opulent Details', 'Close-up velvet, jewelled ornaments and gilded ribbon.', 'Choose one jewel tone and repeat it — abundance needs discipline to stay elegant.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'living-room', 'Family Living Room', 'A bright, lived-in room full of colour, handmade decorations and warmth.', 'Pick four colours and stick to them so a mixed collection still looks coordinated.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'tree', 'Family Collection Tree', 'A tree of mixed, collected and handmade ornaments in happy colours.', 'Hang handmade ornaments where they will be seen — they carry the story.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'mantel', 'Colourful Mantel', 'Bright stockings, paper chains and a cheerful garland.', 'Repeat one bright colour along the whole mantel to tie mismatched pieces together.', 'mantel', 3),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'table', 'Family Christmas Table', 'A colourful, relaxed table with crackers and mixed crockery.', 'Use a plain runner under colourful crockery to stop the table feeling busy.', 'table', 4),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'shelf', 'Colourful Shelf', 'Shelves of handmade decorations, colourful ornaments and cards.', 'Stand Christmas cards along shelves as a free, colourful display.', 'shelf', 5),
((SELECT id FROM public.christmas_looks WHERE slug='colourful-family-christmas'), 'details', 'Handmade Details', 'Close-up felt, paper chains and colourful mixed baubles.', 'Make a paper chain each year and date it — it becomes the family decoration.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'living-room', 'Warm White Living Room', 'Cream, ivory and soft neutrals with warm candlelight throughout.', 'Layer at least three shades of white so the room reads as soft, not flat.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'tree', 'Ivory and Cream Tree', 'A softly lit tree in warm whites, wool and matt ceramic ornaments.', 'Choose matt and woollen finishes over shiny ones to keep the warmth.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'table', 'Cream Christmas Table', 'Warm white linen, cream ceramics and clustered candles.', 'Cluster candles of three heights instead of a single centrepiece.', 'table', 3),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'mantel', 'Soft White Mantel', 'A cream garland with wool stockings and candles.', 'Add a soft wool texture to break up smooth cream surfaces.', 'mantel', 4),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'garland', 'Cream Doorway Garland', 'A soft white garland framing an interior doorway.', 'Frame a doorway rather than the mantel for a fresh place to decorate.', 'garland', 5),
((SELECT id FROM public.christmas_looks WHERE slug='a-white-christmas'), 'details', 'Warm White Details', 'Close-up wool, matt ceramic and cream ribbon.', 'Use natural wood as your accent instead of metal to keep the scheme warm.', 'detail', 6),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'living-room', 'Modern Editorial Living Room', 'A contemporary space with sculptural decoration and a considered palette.', 'Decorate fewer surfaces, but make each one deliberate and sculptural.', 'room', 1),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'tree', 'Contemporary Tree', 'A sculptural tree with oversized matt ornaments and a modern palette.', 'Use fewer, larger ornaments — scale is the current look.', 'tree', 2),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'table', 'Modern Christmas Table', 'Sculptural candles, textured ceramics and a restrained palette.', 'Twisted or sculptural candles instantly modernise a traditional table.', 'table', 3),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'shelf', 'Sculptural Shelf', 'A curated shelf of modern objects, candles and one seasonal accent.', 'Leave half of each shelf empty — negative space is part of the style.', 'shelf', 4),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'window', 'Modern Window Styling', 'Simple hanging forms and warm minimal lighting at the window.', 'Hang a single row of identical forms rather than a mix.', 'window', 5),
((SELECT id FROM public.christmas_looks WHERE slug='latest-trends'), 'details', 'Contemporary Details', 'Close-up matt finishes, textured ceramics and sculptural forms.', 'Mix matt and textured surfaces — gloss reads as dated this season.', 'detail', 6)
